def main():
 result=load(OUT/'results.json');d=result['runs'][0];p=OUT/'run-1';raw=jl(p/'B/public-ws-events.jsonl');rest=jl(p/'B/public-rest-evidence.jsonl');rows=jl(p/'os-samples.jsonl');io=jl(p/'interval-iostat.jsonl');validio=[x for x in io if x.get('parsed') and x['parsed']['interval_valid']];trades=[r for r in raw if r['message']['stream']=='btcusdt@trade'];books=[r for r in raw if r['message']['stream']=='btcusdt@bookTicker'];first={}
