 derived={'boot_UTC':iso(boot,'UTC'),'boot_Europe_Rome':iso(boot,'Europe/Rome'),'window_start_UTC':iso(windowstart['at_ns'],'UTC'),'window_end_UTC':iso(windowend['at_ns'],'UTC'),'window_start_Europe_Rome':iso(windowstart['at_ns'],'Europe/Rome'),'window_end_Europe_Rome':iso(windowend['at_ns'],'Europe/Rome'),'raw_recorded_trade_count':len(trades),'raw_trade_internal_ID_gaps':gaps,'raw_last_trade_source_T_ms':trades[-1]['message']['data']['T'],'max_trade_interreceipt_gap_ms':max((b['received_mono_ns']-a['received_mono_ns'])/1e6 for a,b in zip(trades,trades[1:])),'book_interreceipt_gaps_above_2s':bookgaps,'max_new_trade_receipt_minus_source_T_UNCORRECTED_ms':max(uncorrected),'clock_samples':len(clocks),'clock_offset_ms_minmax':[min(offsets),max(offsets)],'REST_time_request_RTT_ms_minmax':[min(rtts),max(rtts)],'relative_availability':{'REST_precedes_WS_count':len(pairs),'count_above_250ms':sum(x['REST_precedes_WS_ms']>250 for x in pairs),'max_ms':max((x['REST_precedes_WS_ms'] for x in pairs),default=None),'pairs':pairs,'provenance':'PublicREST.get records response_received_mono_ns AFTER await response.json(), same host monotonic clock as received_mono_ns in raw WS. ID/Decimalprice/Decimalqty/T all verified; E is WS-only. No wall/server-clock conversion used.','interpretation':'Relative data availability in this run, NOT isolated network latency or universal provider delay. Unknown relay/network/socket contribution; local event loop maximum29.9ms cannot alone explain measured positive relative gaps.'},'host_window':{'load1_minmax':[min(x['load'][0] for x in rows),max(x['load'][0] for x in rows)],'swap_used_mib_minmax':[min(swaps),max(swaps)],'system_VM_counter_deltas':vm,'first_numeric_iostat_row_excluded':True,'interval_samples':len(validio),'system_CPU_busy_percent_minmax':[min(100-x['parsed']['system_cpu_percent']['idle'] for x in validio),max(100-x['parsed']['system_cpu_percent']['idle'] for x in validio)]},'comparison':{'previous_B_uncensored_rejections':5,'previous_B_uncensored_max_ms':1112.105,'previous_B_raw_rejections':8,'previous_B_CPU_percent_one_core':5.96,'previous_B_frames_per_second':75.54,'postreboot_B_frames_per_second':d['frame_accounting']['received']/d['inputs']['duration'],'postreboot_CPU_seconds_per_1000_frames':d['cpu']['lifetime_seconds']/d['frame_accounting']['received']*1000,'previous_CPU_seconds_per_1000_frames':17.920304/22701*1000,'interpretation':'Same code/guards but different host state/time/market message rate (~half); association with better local timings is not unique proof of swap or reboot causality.'},'verdict':{'local_processing_250ms':'PASS_FOR_THIS_FINITE_WINDOW','local_event_loop_250ms':'PASS_FOR_THIS_FINITE_WINDOW','measurement_window_integrity':'PASS;9 shutdown-only suffix frames outside covered window unpersisted, not hidden','freshness_2s':'FAIL_OBSERVED_INITIALIZED_GATES','initialization':'13 sampled startup UNKNOWN states; no continuous freshness certification','full_feed':'BLOCKED_INITIAL_HISTORICAL_ID_GAP_AND_STRICT_NEWS','overall':'FAIL','repeatability':'NOT_TESTED_AS_PREDECLARED_FIRST_RUN_FRESHNESS_FAILED','forward_activation':'NOT_STARTED','next_minimum_experiment':'No new run now. On the same existing public feed, instrument same-event trade IDs/E/T/monotonic receipt on BOTH independent WS clients plus existing REST snapshots, one bounded observation window, to distinguish per-connection relative arrival from common relay/network delay. Keep guards and entries blocked; do not infer continuous book freshness from unchanged endpoint snapshots.'}}
 con=sqlite3.connect('file:'+str(ROOT/'data/binance-spot/paper.sqlite')+'?mode=ro',uri=True);persisted=json.loads(con.execute('SELECT body FROM snapshot WHERE id=1').fetchone()[0])['binance_spot'];con.close()
 derived['initial_gap_evidence']={'persisted_snapshot_last_trade_id':persisted['last_trade_id'],'first_new_recorded_trade_id':trades[0]['message']['data']['t'],'difference':trades[0]['message']['data']['t']-persisted['last_trade_id'],'internal_recorded_trade_ID_gaps':len(gaps),'interpretation':'Persistent pre-existing ID is older than first new stream by >1000, causing original failclosed initial gap. No IDs were reset; raw window sequence is contiguous. This is not evidence of missing packets inside this window.'}
 derived['frame_counter_checks']={'B_received':d['frame_accounting']['received'],'B_feed_process_count':d['metrics']['stages']['feed_process']['count'],'W_received':d['witness']['counts']['received'],'W_processed':d['witness']['counts']['processed'],'raw_receipt_monotonic_non_decreasing':all(a['received_mono_ns']<=b['received_mono_ns'] for a,b in zip(raw,raw[1:]))}
 result['offline_analysis']=derived;result['postchecks']={'protected_count':179,'all_unchanged':all(hashlib.sha256((ROOT/k).read_bytes()).hexdigest()==h for k,h in load(OUT/'protected-before.json').items()),'port8767_listener':False,'no_Docker_service_calls':True,'no_complete_observer_or_forward_collector_started':True}
